const flask=`<svg viewBox="0 0 40 45" fill="none" aria-hidden="true"><path d="M14 4h13M17 5v15L5 36q-4 6 4 6h23q7 0 3-6L24 20V5M11 31h19" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/><circle cx="20" cy="35" r="2" fill="currentColor"/><circle cx="25" cy="28" r="1.3" fill="currentColor"/></svg>`;
