let academicId='',publicConfig={demo:false,selfRegistration:false},user=null,csrf='',state=null,page='home',term=1,subject='Mathematics',className='SS1',lesson=null,lessonTab='learn',authMode='login',tab='all',files=[],busy=false,widgetBits=Array(6).fill(0);
const termNames=['First term','Second term','Third term'];
const staff=()=>user&&user.role!=='STUDENT';
const ctx=()=>({class:className,subject,term,sessionId:academicId});
const query=()=>new URLSearchParams(ctx()).toString();
async function api(endpoint,data,method){const r=await fetch('/api/'+endpoint,{method:method||(data?'POST':'GET'),credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json'}:{}),'X-CSRF-Token':csrf},...(data?{body:JSON.stringify({...ctx(),...data})}:{})});const value=await r.json();if(!r.ok)throw new Error(value.error||'Something went wrong.');if(Array.isArray(value)&&r.headers.get('X-Content-Revision'))Object.defineProperty(value,'revision',{value:r.headers.get('X-Content-Revision')});return value;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
const initials=name=>name.split(' ').map(v=>v[0]).slice(0,2).join('');
const btn=(action,label,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(title,description,ic='learn')=>`<div class="empty">${icon(ic)}<strong>${esc(title)}</strong><div class="small">${esc(description)}</div></div>`;
const field=(name,label,type='text',value='',required=true)=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${required?'required':''}></div>`;
const area=(name,label,placeholder='',required=true)=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" placeholder="${esc(placeholder)}" ${required?'required':''}></textarea></div>`;
const select=(name,label,options)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options}</select></div>`;
const options=(arr,value)=>arr.map(v=>`<option value="${esc(typeof v==='object'?v.id:v)}" ${value===(typeof v==='object'?v.id:v)?'selected':''}>${esc(typeof v==='object'?v.name:v)}</option>`).join('');
function passwordScreen(){$('#app').innerHTML=`<main class="auth"><section class="auth-form-wrap" style="margin:auto"><div class="auth-form">${brand}<h2>Choose your own password</h2><p class="muted">You signed in with a temporary password. Set a new one to continue. Use at least 12 characters.</p><form id="password-form" data-form="change-password"><div class="field"><label for="cp-current">Temporary password</label><input id="cp-current" name="currentPassword" type="password" required autocomplete="current-password"></div><div class="field"><label for="cp-new">New password</label><input id="cp-new" name="newPassword" type="password" required minlength="12" autocomplete="new-password"></div><div class="field"><label for="cp-confirm">Confirm new password</label><input id="cp-confirm" name="confirmPassword" type="password" required minlength="12" autocomplete="new-password"></div><div id="auth-message" role="alert" aria-live="polite"></div><button class="btn primary" type="submit">Save password and continue</button><button class="btn quiet" type="button" data-action="logout">Sign out</button></form></div></section></main>`;$('#cp-new').focus();}
async function enterApp(){academicId='';className=user.class||'SS1';const profile=await api('me');if(user.role==='TEACHER'&&profile.allocations?.length){className=profile.allocations[0].class;subject=profile.allocations[0].subject;}academicId=profile.currentSessionId;page=user.role==='ADMIN'?'admin':user.role==='TEACHER'?'teaching':'home';term=profile.currentTerm||1;await refresh();render();}
function auth(){user=null;$('#app').innerHTML=`<main class="auth"><section class="auth-visual"><img class="auth-photo" src="/assets/school-building.jpeg" alt="Grace-Field College, Ibadan building"><div class="auth-brand"><img src="/assets/school-logo.png" alt="Grace-Field school crest"><span>GRACE-FIELD<br><small style="font-size:9px;letter-spacing:2px;font-weight:400">COLLEGE · IBADAN</small></span></div><div class="auth-caption"><span class="eyebrow">A SPACE TO WONDER. A PLACE TO GROW.</span><h1>Big possibilities.<br>One curious mind.</h1><p>Learn a little. Ask a lot. Build the confidence to take on your world, one discovery at a time.</p><span class="small">JSS1 — SS3 &nbsp; · &nbsp; Made for every learner.</span></div></section><section class="auth-form-wrap"><div class="auth-form">${brand}<h2>${authMode==='login'?'Welcome back.':'Your next chapter starts here.'}</h2><p class="muted">${authMode==='login'?'Your learning journey is waiting. Let’s pick up where you left off.':'Join your school’s learning community. Your administrator will approve your account.'}</p><form id="auth-form" data-form="auth">${authMode==='register'?field('name','Full name')+`<div class="grid form-grid">${select('class','Your class',options(['JSS1','JSS2','JSS3','SS1','SS2','SS3'],'SS1'))}${field('admission','Admission number')}</div>`+field('guardian','Parent / guardian phone','tel'):''}${field('email','School email','email')}<div class="field"><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" required minlength="${authMode==='register'?10:1}" autocomplete="${authMode==='login'?'current-password':'new-password'}"><button type="button" data-action="show-password">Show</button></div></div><div id="auth-message" role="alert"></div><button class="primary gap" type="submit">${authMode==='login'?'Sign in to your lab':'Create student account'} &nbsp; →</button></form><p class="small muted" style="text-align:center">${authMode==='login'?'New to the lab?':'Already registered?'} ${btn('auth-toggle',authMode==='login'?'Create an account':'Sign in','subtle')}</p>${publicConfig.demo?`<div class="auth-demo"><strong>Development sandbox</strong><br>Choose a role to enter the development sandbox. No production credentials are used.<div class="row" style="gap:7px;margin-top:9px">${['Student','Teacher','Admin'].map(v=>btn('demo',v,'',`data-role="${v.toLowerCase()}"`)).join('')}</div></div>`:''}<p class="small muted" style="font-size:9px;text-align:center;margin-top:25px">A little curiosity. A world of possibility.</p></div></section></main>`;}
const navigation=[['home','Home','home'],['learn','My learning','learn'],['assignments','Assignments','assignment'],['notes','My notes','notes'],['scores','Test & exam scores','scores'],['progress','My progress','progress'],['questions','Class discussions','question'],['recordings','Class recordings','recording'],['live','Live classes','live']];
const names=Object.fromEntries(navigation.map(v=>[v[0],v[1]]));Object.assign(names,{admin:'School management',teaching:'Teaching workspace',lesson:'My learning',more:'Your lab'});
async function refresh(){state=await api('state?'+query());user=state.user;if(user.role==='STUDENT')className=user.class;}
async function navigate(next){page=next;tab='all';lesson=null;await refresh();render();window.scrollTo({top:0,behavior:'instant'});}
function progressValues(){const completed=state.progress.filter(p=>p.complete).length,total=state.weeks.reduce((n,w)=>n+w.lessons.length,0)*(staff()?Math.max(1,state.students.filter(s=>s.status==='ACTIVE').length):1);return {completed,total,percent:total?Math.round(completed/total*100):0,submitted:state.submissions.filter(s=>s.kind==='assignment').length,notes:state.submissions.filter(s=>s.kind==='note').length,accuracy:state.progress.length?Math.round(state.progress.reduce((a,p)=>a+(p.accuracy||0),0)/state.progress.length):0};}
function render(){if(!user)return auth();const content={home:dashboard,learn:learning,lesson:lessonPage,assignments:assignments,notes:notes,scores:scores,progress:progressPage,questions:questions,recordings:recordings,live:live,admin:admin,teaching:teaching,more:more,students:studentPage}[page]||dashboard;$('#app').innerHTML=`<a class="skip-link" href="#main-content">Skip to main content</a><div class="shell"><aside class="sidebar" aria-label="Account and learning menu">${brand}<div class="school"><img src="/assets/school-logo.png" alt="Grace-Field College, Ibadan logo"><span>GRACE-FIELD COLLEGE<br>Raising young minds for future impact.</span></div><div class="nav-label">YOUR LEARNING SPACE</div><nav class="nav" aria-label="Main navigation">${navigation.map(([id,label,ic])=>`<button data-page="${id}" class="${page===id||id==='learn'&&page==='lesson'?'active':''}">${icon(ic)}<span>${staff()&&id==='notes'?'Notes & review':staff()&&id==='progress'?'Class progress':label}</span>${id==='assignments'&&state.assignments.length?`<span class="count">${state.assignments.length}</span>`:''}</button>`).join('')}${staff()?`<div class="nav-label">TEACHER WORKSPACE</div><button data-page="students" class="${page==='students'?'active':''}">${icon('users')}Students</button><button data-page="teaching" class="${page==='teaching'?'active':''}">${icon('settings')}Teaching workspace</button>`:''}${user.role==='ADMIN'?`<button data-page="admin" class="${page==='admin'?'active':''}">${icon('users')}School management</button>`:''}</nav><div class="sidebar-bottom"><div class="curiosity"><strong>Stay curious. Keep growing.</strong>Every question is the beginning<br>of a new discovery. ${icon('sun')}</div><div class="profile"><div class="avatar">${esc(initials(user.name))}</div><div style="flex:1"><strong>${esc(user.name)}</strong><small>${esc(user.role==='STUDENT'?user.class+' · Student':user.role==='ADMIN'?'Administrator':'Subject teacher')}</small></div>${btn('logout',icon('logout'),'subtle','aria-label="Sign out"')}</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span class="home-crumb">My workspace</span>${icon('chevron')}<strong>${esc(names[page]||'Home')}</strong></div><div class="row"><span class="session-label">${esc(sessionLabel())} session</span><label class="sr-only" for="term-switch">Academic term</label><select id="term-switch" class="term-select">${termNames.map((v,i)=>`<option value="${i+1}" ${term===i+1?'selected':''}>${v} ${i+1>(state.currentTerm||1)?'· Upcoming':''}</option>`).join('')}</select>${btn('theme',icon('sun'),'subtle','aria-label="Toggle light or dark mode"')}<span class="avatar">${esc(initials(user.name))}</span></div></header><main class="content" id="main-content" tabindex="-1">${staff()?filters():studentFilters()}${content()}<footer class="bottom-note"><span>© ${new Date().getFullYear()} Olawale’s Lab · Grace-Field College, Ibadan</span><span>Learn with purpose. Grow with confidence.</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['home','Home','home'],['learn','Learn','learn'],['assignments','Work','assignment'],['notes','Notes','notes'],['more','More','more']].map(([id,label,ic])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav></div>`;if(page==='lesson')initWidget();if(page==='lesson'||page==='questions'||page==='notes')loadImages();}
function studentFilters(){return `<div class="row filter-row"><label>Learning subject<select id="subject-switch">${options(state.subjects,subject)}</select></label><span class="badge">${esc(className)} · ${termNames[term-1]}</span></div>`;}
function filters(){let allocations=state.allocations;const classes=user.role==='ADMIN'?state.classes:[...new Set(allocations.map(a=>a.class))];const subjects=user.role==='ADMIN'?state.subjects:[...new Set(allocations.filter(a=>a.class===className).map(a=>a.subject))];return `<div class="row filter-row"><label>Class<select id="class-switch">${options(classes,className)}</select></label><label>Subject<select id="subject-switch">${options(subjects,subject)}</select></label><span class="badge">${user.role==='ADMIN'?'Administrator':'Assigned classes only'}</span></div>`;}
function heading(title,sub,action=''){return `<div class="welcome"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const art=`<svg class="hero-art" viewBox="0 0 280 250" fill="none" aria-hidden="true"><ellipse cx="153" cy="227" rx="106" ry="11" fill="#c3def5"/><circle cx="187" cy="111" r="80" fill="#cde3fa"/><path d="m67 180 103-17 57 32-108 22Z" fill="#5899ca"/><path d="m68 180 1 10 50 31 109-22-1-9-108 20Z" fill="#226896"/><path d="m69 173 105-19 47 28-105 22Z" fill="#f5faff"/><path d="m63 168 103-18 58 30-108 22Z" fill="#df809b"/><path d="m63 168 1 10 52 31 109-22-1-10-108 20Z" fill="#b94b70"/><path d="m76 162 87-17 48 26-89 18Z" fill="#fff0f3"/><path d="m94 81 53 17 58-12-8 82-55 15-54-24Z" fill="#f1f8ff" stroke="#367ba9" stroke-width="2"/><path d="m147 98-5 85 M99 93l34 12 M98 104l34 12 M97 115l34 12 M96 126l34 12 M156 108l35-9 M155 119l34-9 M154 130l34-9 M153 141l34-9" stroke="#a9cce6" stroke-width="2"/><path d="m94 81-7 78 55 24 55-15 8-82" stroke="#4189bb" stroke-width="3"/><path d="m223 93 18 8-45 91-14 7 2-16Z" fill="#ad3459"/><path d="m225 96 8 4-43 85-5 10-1-12Z" fill="#eaa8bc"/><path d="m182 199 3-16 11 9Z" fill="#f3d6df"/><path d="m182 199 2-7 5 3Z" fill="#174e7a"/><path d="M69 91c-15-21-25-12-23 0 2 9 17 15 17 15s9-10 6-15" fill="#78abd0"/><path d="m60 133 7-34 M60 120c-20-2-21-16-11-18 10-1 14 7 14 7 M64 111c19-7 21-21 11-22-10 0-13 12-13 12" stroke="#427ca5" stroke-width="2"/><path d="m47 130 26 2-6 27H54Z" fill="#c46d8a"/><path d="m241 57 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z M99 42l2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#81b5d9"/><circle cx="211" cy="35" r="3" fill="#b4d7ef"/><circle cx="38" cy="155" r="3" fill="#b4d7ef"/></svg>`;
function dashboard(){const p=progressValues(),first=state.weeks.flatMap(w=>w.lessons.filter(l=>l.available||w.unlocked)).find(l=>!state.progress.some(p=>p.lesson===l.id&&p.complete));const name=staff()?user.name:user.name.split(' ')[0],submitted=new Set(state.submissions.filter(v=>v.kind==='assignment').map(v=>v.assignment)),pending=state.assignments.filter(a=>a.available!==false&&!submitted.has(a.id));const latest=state.submissions.filter(v=>v.feedback).at(-1);const live=state.resources.find(r=>r.type==='live');return `${heading(`${staff()?'Welcome back':'Hello'}, ${esc(name)} <span style="font-size:22px">☀</span>`,staff()?'A good day to inspire a little curiosity. Here’s your class at a glance.':'A little progress every day adds up. Ready to discover something new?',`<span class="date">${icon('calendar')}${new Intl.DateTimeFormat('en-NG',{weekday:'long',day:'numeric',month:'short',timeZone:'Africa/Lagos'}).format(new Date())}</span>`)}<div class="dashboard-columns"><div><section class="hero"><div class="hero-copy"><span class="badge">${esc(className)} &nbsp;·&nbsp; ${termNames[term-1]} &nbsp;·&nbsp; ${esc(sessionLabel())}</span><h2>A curious mind.<br>A brighter tomorrow.</h2><p>Your next discovery is just a lesson away.<br>Take your time. Make it yours.</p>${btn(first?'open-lesson':'go-learn',`Let’s keep learning ${icon('arrow')}`,'primary',first?`data-id="${first.id}"`:'')}</div>${art}</section><div class="stats"><div class="card stat"><span class="stat-icon">${icon('learn')}</span><div><strong>${p.completed}<span class="muted" style="font-size:12px"> / ${p.total}</span></strong><small>Lessons completed</small></div></div><div class="card stat"><span class="stat-icon">${icon('assignment')}</span><div><strong>${pending.length.toString().padStart(2,'0')}</strong><small>Assignments to do</small></div></div><div class="card stat"><span class="stat-icon">${icon('progress')}</span><div><strong>${p.accuracy}<span style="font-size:13px">%</span></strong><small>Practice accuracy</small></div></div></div><div class="section-head"><h2>Your learning, your pace</h2>${btn('go-learn',`View learning ${icon('chevron')}`)}</div><div class="grid"><section class="card subject-card"><div class="row between"><span class="subject-icon">∑</span><span class="badge">${state.weeks.some(w=>w.unlocked)?'Ready to learn':'Awaiting content'}</span></div><h3>${esc(subject)}</h3><p>${first?esc(state.weeks.find(w=>w.lessons.some(l=>l.id===first.id))?.title):'Your teacher will open your next lesson.'}</p><div class="progress-line"><span style="width:${p.percent}%"></span></div><div class="progress-text"><span>${p.completed} of ${p.total} lessons</span><span>${p.percent}%</span></div>${btn(first?'open-lesson':'go-learn',`Continue learning ${icon('arrow')}`,'',first?`data-id="${first.id}"`:'')}</section><section class="card subject-card"><div class="row between"><span class="subject-icon" style="background:#fff0f3;color:#a80029">Aa</span><span class="badge gray">Coming soon</span></div><h3>More to discover</h3><p>Your teachers are preparing your next subjects. Good things take a little care.</p><div class="progress-line"><span style="width:0%"></span></div><div class="progress-text"><span>JSS1 — SS3</span><span>3 terms</span></div>${btn('go-live',`Explore class resources ${icon('arrow')}`)}</section></div><div class="section-head gap"><h2>A little work, a lot of growth</h2>${btn('go-assignments',`All assignments ${icon('chevron')}`)}</div><section class="card">${pending.length?pending.slice(0,3).map(a=>`<div class="assignment-row"><span class="tile-icon">${icon('assignment')}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.subject)} · Due ${esc(assignmentDeadline(a.due))}</p></div>${btn('assignment-open','View →','',`data-id="${a.id}"`)}</div>`).join(''):empty('You’re all caught up','New assignments from your teacher will appear here.','check')}</section></div><aside class="dashboard-aside"><div class="stack"><section class="card aside-card"><div class="row between"><h2 style="margin:0">Growing every day</h2><span class="small muted">${termNames[term-1]}</span></div><div class="ring" style="--value:${p.percent}%"><div><strong>${p.percent}%</strong><small>Learning progress</small></div></div><div class="legend"><span><i class="dot"></i>Completed</span><span><i class="dot light"></i>Still to explore</span></div><div class="mini-stat"><span>Lessons completed</span><strong>${p.completed} / ${p.total}</strong></div><div class="mini-stat"><span>Assignments submitted</span><strong>${p.submitted}</strong></div></section><section class="card aside-card live-card"><span class="eyebrow">${icon('live')} &nbsp; LEARN TOGETHER</span><h3>${live?esc(live.title):'There’s a place for<br>every question.'}</h3><p>${live?esc(live.day||'Join your subject’s live classroom.'):'Your teacher’s next live class will appear right here. Stay curious until then.'}</p>${live?.url?`<a href="${esc(live.url)}" target="_blank" rel="noopener noreferrer">Join live class &nbsp; ↗</a>`:btn('go-live','Visit live classroom &nbsp; →')}</section><section class="card aside-card"><h2>A note from your teacher</h2><div class="feedback"><strong>${latest?'Feedback on your work':'A fresh start awaits'}</strong>${latest?esc(latest.feedback):'Your teacher’s personal feedback will appear here once your work has been reviewed.'}<small>${latest?'Keep learning. Keep growing.':'Submit your first assignment or notes to get started.'}</small></div></section></div></aside></div>`;}
function learning(){return heading('A world to discover.','Small steps. Big understanding. Open a week and make a new idea your own.')+(state.termLocked?empty('This term is not open','Your administrator controls access to each term.','lock'):state.weeks.length?`<div class="stack">${state.weeks.map(w=>`<section class="card ${w.unlocked?'':'week-locked'}"><div class="week"><span class="week-number">${String(w.id).padStart(2,'0')}</span><div class="week-title"><h3>${esc(w.title)}</h3><p>${esc(w.subtitle)}</p></div><span class="badge ${w.unlocked?'':'gray'}">${icon(w.unlocked?'check':'lock')}${w.unlocked?'Open':'Locked'}</span></div>${w.unlocked||staff()?`<div class="lesson-links">${w.lessons.map(l=>btn('open-lesson',`<span>${state.progress.some(p=>p.lesson===l.id&&p.complete)?'✓ &nbsp;':''}${esc(l.title)}</span><span class="small muted">${l.minutes} min &nbsp; →</span>`,'',`data-id="${l.id}"`)).join('')}</div>`:''}</section>`).join('')}</div>`:empty('Your learning space is ready','Lessons for this class, subject and term have not been published yet.'));}
// Question prompts may contain inline mathematics between dollar signs, e.g. "Solve $x^2-4=0$".
function promptHTML(text){return String(text??'').split(/(\$[^$\n]{1,300}\$)/g).map(part=>/^\$[^$\n]+\$$/.test(part)&&part.length>2?`<span class="math-source" data-math-tex="${esc(part.slice(1,-1))}" data-math-display="false"><code aria-label="Mathematical source">${esc(part.slice(1,-1))}</code></span>`:esc(part)).join('');}
// One answer control for every question kind. Several correct choices are checkboxes that share the name.
function answerField(q,name,id,label){
 if(q.kind==='multi')return `<fieldset class="multi-answer"><legend class="sr-only">${esc(label)}. Choose every correct answer.</legend><p class="small muted">Choose every correct answer.</p>${(q.options||[]).map((o,n)=>`<label class="check"><input type="checkbox" name="${esc(name)}" value="${esc(o)}" data-multi> <span>${promptHTML(o)}</span></label>`).join('')}</fieldset>`;
 if(q.kind==='choice'||q.kind==='boolean')return `<select ${id?`id="${esc(id)}" `:''}name="${esc(name)}" aria-label="${esc(label)}" required><option value="">Choose an answer</option>${options(q.kind==='boolean'?['true','false']:q.options)}</select>`;
 return `<input ${id?`id="${esc(id)}" `:''}name="${esc(name)}" aria-label="${esc(label)}" placeholder="Your answer" required autocomplete="off">`;
}
// Read a form's answers as {name:value}; several checked boxes join with "|".
function formAnswers(form){const out={};for(const [key,value] of new FormData(form)){out[key]=key in out?out[key]+'|'+value:value;}return out;}
function questionList(qs,prefix='practice'){return qs.map((q,i)=>`<section class="question" id="${prefix}-${q.id}"><span class="badge ${q.difficulty==='Exam-style'?'orange':''}">${esc(q.difficulty)} · ${i+1} of ${qs.length}</span><p>${promptHTML(q.prompt)}</p>${q.marks>1?`<span class="small muted">${q.marks} marks</span>`:''}<form data-form="answer" data-question="${q.id}"><div class="row">${answerField(q,'answer','',`Answer for question ${i+1}`)}<button class="primary" type="submit">Check answer</button>${btn('hint','A little hint','',`type="button" data-id="${q.id}"`)}</div><div class="answer-feedback" role="status"></div></form></section>`).join('');}
function lessonPage(){if(!lesson)return empty('Loading your lesson','Please wait.');const p=state.progress.find(p=>p.lesson===lesson.id);const qs=state.questions.filter(q=>q.lesson===lesson.id);const r=state.reflections.find(r=>r.lesson===lesson.id&&r.student===user.id);return `${heading(esc(lesson.title),`${esc(subject)} · Week ${lesson.week} · ${lesson.minutes} minutes`,btn('go-learn','← All lessons'))}<div class="tabs">${[['learn','Learn & explore'],['practice','Practice · 45'],['quiz','Quiz & mastery'],['discuss',`Questions · ${qs.length}`],['reflect','My reflection']].map(([id,label])=>btn('lesson-tab',label,lessonTab===id?'active':'',`data-tab="${id}"`)).join('')}</div><div class="lesson-layout"><div class="stack">${lessonTab==='learn'?`<section class="card objective"><span class="eyebrow">YOUR LITTLE LEARNING GOALS</span><ul class="checklist">${lesson.objectives.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section><section class="card lesson-copy"><h2>Let’s make sense of it.</h2><p>${esc(lesson.explain)}</p><div class="callout"><strong>Key idea</strong><br>Understand the method, then explain it in your own words.</div><h2 class="gap">See it, step by step.</h2><p>${esc(lesson.example.prompt)}</p><div class="example-step" id="worked-step">Think about the method you would use before revealing the working.</div>${btn('show-example','Show the working →','gap')}<h2 class="gap">Out of the classroom, into your world.</h2><p>${esc(lesson.realLife)}</p></section><section class="card"><span class="eyebrow">THE EXPERIMENT CORNER</span><h2 class="gap">Change something. Discover something.</h2>${widget()}</section><section class="card"><h2>Watch, then wonder.</h2>${resourceVideos(lesson.week)}<details class="gap"><summary>Learn a little more</summary><p>${esc(lesson.explain)}</p><p>Try teaching this idea to a friend, then compare two different methods. Your class recordings and teacher lesson notes offer another way to revisit it.</p>${btn('go-recordings','Open class recordings')}${btn('go-notes','Teacher lesson notes')}</details></section><section class="card"><h2>Your quick checkpoint</h2>${questionList(lesson.questions.filter(q=>q.stage==='diagnostic'),'checkpoint')}</section><section class="card"><h2>Take these ideas with you.</h2><ul class="checklist">${lesson.summary.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><div class="row">${btn('lesson-tab','Try the practice →','primary','data-tab="practice"')}${btn('lesson-tab','Write my reflection','','data-tab="reflect"')}</div></section>`:lessonTab==='practice'||lessonTab==='quiz'?`<section class="card"><h2>${lessonTab==='quiz'?'Show what you know.':'Progress takes practice.'}</h2><p class="muted small">${lessonTab==='quiz'?'Ten questions across this topic. Check each answer for feedback.':'Work from beginner to challenge questions. Your teacher sets the practice completion threshold; assessment scores determine mastery.'}</p>${questionList(lessonTab==='quiz'?lesson.quiz:lesson.questions.filter(q=>!q.stage||['practice','application'].includes(q.stage)))}</section>`:lessonTab==='discuss'?`<section class="card"><h2>Good questions belong here.</h2><p class="muted small">Everyone in your class and your assigned teachers can see this conversation.</p>${discussionForm()}${threads(qs)}</section>`:`<section class="card"><h2>Pause. Think. Make it yours.</h2><p class="muted small">A short reflection helps turn today’s lesson into lasting understanding.</p><form data-form="reflection">${area('learnt','In 2–3 sentences, what did I learn today?','The idea that clicked for me was…')}${area('concept','Explain one important concept in your own words.','A short explanation is enough.',false)}${area('difficult','Which part was difficult?','Tell your teacher where you got stuck.',false)}${select('confidence','How confident do you feel?',options(['1','2','3','4','5'],'3'))}${area('question','What question do I still have?','What would you like your teacher to explain? Write “None for now” if you are ready.')}<div class="row"><button class="primary">Submit reflection</button><button type="submit" name="saveDraft" value="true">Save a draft</button></div></form>${r?`<div class="feedback gap"><strong>Your latest reflection</strong>${esc(r.learnt)}<p>${esc(r.question)}</p>${r.reply?`<strong>Teacher feedback</strong>${esc(r.reply)}`:'<small>Your teacher can read and respond to this reflection.</small>'}</div>`:''}</section>`}</div><aside class="card sticky"><h3>Your lesson journey</h3><ul class="checklist"><li>Read and explore</li><li>${p?.accuracy||0}% practice accuracy</li><li>${p?.reflectionDone?'Reflection submitted':'Reflection still to write'}</li></ul><span class="badge ${p?.complete?'':'orange'}">${p?.complete?'Lesson completed':'Keep going. You’ve got this.'}</span><hr class="divider"><p class="small muted">Your progress is saved to your school account. You can come back whenever you need.</p>${btn('go-questions',`${icon('question')} Ask your class`,'subtle')}<hr class="divider"><span class="small muted">Practice goal: 60%<br>Reflection: required</span></aside></div>`;}
function widget(){if(subject!=='Mathematics'||className!=='SS1'||term!==1)return `<div class="widget"><h3>Try it for yourself</h3><p>${esc(lesson.experiment||'Use your teacher’s lesson notes to try an activity, compare your observations, and write what you discovered in your reflection.')}</p></div>`;const w=lesson.week;if(w===1)return `<div class="widget"><p class="small">Flip the binary switches. Each place is worth twice the one to its right.</p><div class="bits">${widgetBits.map((b,i)=>btn('bit',`${b}<br><small>${2**(5-i)}</small>`,b?'on':'',`data-i="${i}" aria-label="Toggle bit worth ${2**(5-i)}"`)).join('')}</div><output id="bits-value"></output><div class="grid form-grid">${field('base-value','Decimal number','number','25')}${select('base-target','Convert to base',options(['2','5','8'],'2'))}</div><output id="base-output"></output></div>`;
if(w===2)return `<div class="widget">${field('index-base','Base','number','2')}${field('index-p','First power','number','3')}${field('index-q','Second power','number','4')}<output id="index-output"></output></div>`;
if(w===3||w===4||w===5)return `<div class="widget">${field('log-value','Positive number','number','45.6')}<output id="log-output"></output><p class="small muted">The generated four-figure table below gives mantissas for numbers 1.00–9.99. Scale your number using its characteristic.</p><details><summary>Open the logarithm table and guided lookup</summary><p id="log-guide" class="small"></p><div class="table-wrap" style="max-height:280px"><table><thead><tr><th>Row</th>${Array.from({length:10},(_,i)=>`<th>${i}</th>`).join('')}</tr></thead><tbody>${Array.from({length:90},(_,i)=>`<tr><th>${i+10}</th>${Array.from({length:10},(_,j)=>`<td>${Math.round(Math.log10((i+10)/10+j/100)*10000).toString().padStart(4,'0')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>${field('antilog-value','Signed logarithm for antilog','number','1.6590')}<output id="antilog-output"></output></div>`;
if(w===6)return `<div class="widget">${field('variation-k','Constant k','number','4')}${field('variation-x','x (positive)','number','3')}<output id="variation-output"></output><svg class="plot" id="variation-plot" viewBox="0 0 400 280"></svg></div>`;
if(w===7)return `<div class="widget"><p>Start with v = u + at. Rearrange: t = (v − u) / a.</p>${field('formula-v','Final speed v','number','20')}${field('formula-u','Initial speed u','number','5')}${field('formula-a','Acceleration a (nonzero)','number','3')}<output id="formula-output"></output></div>`;
return `<div class="widget"><p class="small">Explore y = ax² + bx + c. The coefficient a must be nonzero.</p><div class="grid three">${['a','b','c'].map((n,i)=>field('quad-'+n,n,'number',[1,-2,-3][i])).join('')}</div><svg class="plot" id="quad-plot" viewBox="0 0 400 280"></svg><output id="quad-output" style="font-size:16px"></output><div id="quad-table" class="small"></div></div>`;}
function initWidget(){updateWidgets();}
function updateWidgets(){const val=id=>Number($('#'+id)?.value);if($('#bits-value')){const n=widgetBits.reduce((a,b,i)=>a+b*2**(5-i),0);$('#bits-value').textContent=`${widgetBits.join('')}₂ = ${n}₁₀`;const n2=val('base-value'),base=val('base-target');$('#base-output').textContent=Number.isSafeInteger(n2)&&n2>=0?`${n2}₁₀ = ${n2.toString(base)} (base ${base})`:'Enter a nonnegative whole number.';}
if($('#index-output')){const a=val('index-base'),p=val('index-p'),q=val('index-q');$('#index-output').textContent=`${a}^${p} × ${a}^${q} = ${a}^${p+q} = ${Number((a**(p+q)).toPrecision(8))}`;}
if($('#log-output')){const n=val('log-value'),log=Math.log10(n),ch=Math.floor(log);$('#log-output').textContent=n>0?`log₁₀(${n}) = ${log.toFixed(4)} · characteristic ${ch}, mantissa ${(log-ch).toFixed(4)}`:'Enter a positive number.';const scaled=n/10**ch,row=Math.floor(scaled*10),column=Math.floor(scaled*100)%10,fourth=Math.floor(scaled*1000)%10;$('#log-guide').textContent=n>0?`Write ${n} as ${scaled.toFixed(3)} × 10^${ch}. Find row ${row}, column ${column}. For fourth digit ${fourth}, the interpolated mean difference is about ${Math.round((Math.log10((Math.floor(scaled*100)+1)/100)-Math.log10(Math.floor(scaled*100)/100))*10000*fourth/10)} units in the fourth decimal place. Add it to the table entry, then add the signed characteristic ${ch}.`:'';$('#antilog-output').textContent=`Antilog = ${Number((10**val('antilog-value')).toPrecision(7))}`;}
if($('#variation-output')){const k=val('variation-k'),x=val('variation-x');$('#variation-output').textContent=x>0?`Direct: y = ${k*x} · Inverse: y = ${(k/x).toFixed(3)}`:'Use a positive x.';plot($('#variation-plot'),v=>k*v,-1,10,-2,Math.max(15,Math.abs(k)*10),v=>k/v);}
if($('#formula-output')){const v=val('formula-v'),u=val('formula-u'),a=val('formula-a');$('#formula-output').textContent=a!==0?`t = (${v} − ${u}) / ${a} = ${Number(((v-u)/a).toPrecision(8))}`:'Acceleration must be nonzero.';}
if($('#quad-plot')){const a=val('quad-a'),b=val('quad-b'),c=val('quad-c'),d=b*b-4*a*c,x=-b/(2*a);plot($('#quad-plot'),x=>a*x*x+b*x+c,-6,6,-10,14);$('#quad-output').textContent=a!==0?`Discriminant ${d}; vertex (${x.toFixed(2)}, ${(a*x*x+b*x+c).toFixed(2)}). ${d>=0?`Roots ${((-b-Math.sqrt(d))/(2*a)).toFixed(2)}, ${((-b+Math.sqrt(d))/(2*a)).toFixed(2)}`:'No real roots.'}`:'Choose a nonzero a for a quadratic.';$('#quad-table').textContent=[-2,-1,0,1,2,3,4].map(x=>`x=${x} → y=${a*x*x+b*x+c}`).join(' · ');}}
function plot(svg,fn,xmin,xmax,ymin,ymax,fn2){const W=400,H=280,X=x=>(x-xmin)/(xmax-xmin)*W,Y=y=>H-(y-ymin)/(ymax-ymin)*H;let lines='';for(let x=Math.ceil(xmin);x<=xmax;x++)lines+=`<path d="M${X(x)} 0V${H}" stroke="#e7f1fb"/>`;for(let y=Math.ceil(ymin);y<=ymax;y+=2)lines+=`<path d="M0 ${Y(y)}H${W}" stroke="#e7f1fb"/>`;lines+=`<path d="M${X(0)} 0V${H} M0 ${Y(0)}H${W}" stroke="#52657d"/>`;for(const f of [fn,fn2].filter(Boolean)){let d='',pen=false;for(let i=0;i<=W;i++){const y=f(xmin+i/W*(xmax-xmin));if(!Number.isFinite(y)||y<ymin||y>ymax){pen=false;continue;}d+=`${pen?'L':'M'}${i} ${Y(y)} `;pen=true;}lines+=`<path d="${d}" fill="none" stroke="${f===fn?'#0064a8':'#b9002c'}" stroke-width="2.5"/>`;}svg.innerHTML=lines;}
function uploadBox(purpose){return `<div class="upload-area">${icon('camera')}<p class="small"><strong>Snap it. Upload it. Make it count.</strong><br>Photograph each page in good light.</p><label class="small" for="camera-input">Take a photo</label><input id="camera-input" type="file" accept="image/*" capture="environment" multiple data-purpose="${purpose}"><label class="small" for="gallery-input">Or choose photos from your gallery</label><input id="gallery-input" type="file" accept="image/*" multiple data-purpose="${purpose}"><small>Up to 10 pages · Images compressed before upload<br>${purpose==='lesson-note'?'Published lesson notes are shared with approved students in this class.':'Only you, your subject teacher and school admin can see submitted work.'}</small><div id="upload-preview" class="file-preview"></div><div id="upload-status" role="status"></div></div>`;}
function submissionFeedback(sub){return sub?`<div class="feedback gap"><strong>${esc(sub.status)} ${sub.score!=null?`· ${sub.score}/${sub.max||100}`:''}</strong>${esc(sub.feedback||'Your work is with your teacher. Feedback will appear here after review.')}<div class="row gap">${(sub.files||[]).map(f=>btn('view-file',`${icon('notes')} View page`,'',`data-id="${f}"`)).join('')}</div></div>`:'';}
const assignmentStates={DRAFT:'Draft',LOCKED:'Locked',SCHEDULED:'Scheduled',PUBLISHED:'Released'};
function assignmentScope(a){
 const all=state.weeks.flatMap(w=>w.lessons),titles=(a.lessons||[]).map(id=>all.find(l=>l.id===id)?.title).filter(Boolean);
 if(a.scope==='LESSON')return titles[0]?`Follows the lesson “${titles[0]}”`:'Follows one lesson';
 if(a.scope==='WEEK_END')return `End of Week ${a.week}`;
 return titles.length?`Covers: ${titles.join(', ')}`:`General · Week ${a.week||''}`.trim();
}
function assignmentCard(a){
 const subs=state.submissions.filter(v=>v.assignment===a.id),mine=subs.find(v=>v.student===user.id),locked=!staff()&&a.available===false;
 const how=a.mode==='ONLINE'?'Answer on the platform':'Write in your note, then upload a photo';
 return `<article class="thread"><div class="row between"><span class="badge">${esc(a.subject)}</span>${staff()?`<span class="badge ${a.status==='PUBLISHED'?'':'orange'}">${assignmentStates[a.status]||'Released'}${a.status==='PUBLISHED'&&a.available===false?' · waiting for its lesson':''}</span>`:''}<span class="small muted">${a.due?'Due '+esc(assignmentDeadline(a.due)):'No deadline yet'}</span></div>
 <h2 class="gap">${esc(a.title)}</h2><p class="small muted">${esc(assignmentScope(a))}${a.scope||a.mode?' · '+how:''}</p>
 ${locked?'<p class="callout">🔒 Locked. Your teacher will release this after teaching the topic in class.</p>':`<p class="muted small">${esc((a.instructions||'').slice(0,300))}</p>`}
 ${staff()?`<div class="row">${btn('review-assignment',`Review ${subs.length} submission${subs.length===1?'':'s'}`,'primary',`data-id="${a.id}"`)}${a.status==='PUBLISHED'?btn('assignment-lock','Lock again','',`data-id="${a.id}"`):btn('assignment-release-open','Release to students','primary',`data-id="${a.id}"`)}${btn('allow-resubmit',a.resubmission?'Disable resubmission':'Allow resubmission','',`data-id="${a.id}" data-enabled="${a.resubmission?'0':'1'}"`)}</div>`:locked?'':btn('assignment-open',mine?(a.resubmission?'View / retake':'View my result'):a.mode==='ONLINE'?'Start assignment':'Open & submit assignment','primary',`data-id="${a.id}"`)}${!staff()?submissionFeedback(mine):''}</article>`;
}
function assignments(){
 const groups=new Map();for(const a of state.assignments){const key=a.week||0;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(a);}
 return heading('A little work. A lot of growth.',staff()?'Write assignments in Lesson Studio, then release them here when you have taught the topic.':'Put your understanding into practice, then share your working with your teacher.',staff()?btn('studio-open',`${icon('plus')} Write an assignment`,'primary'):'')+(!groups.size?empty('Nothing due just yet','Assignments for the selected class and term will appear here.','assignment'):[...groups].sort(([a],[b])=>a-b).map(([id,list])=>`<section class="card gap"><h2>${id?'Week '+id+' · '+esc(state.weeks.find(w=>w.id===id)?.title||'Weekly topic'):'Earlier assignments'}</h2>${list.map(assignmentCard).join('')}</section>`).join(''));
}
function notes(){const ns=state.submissions.filter(s=>s.kind==='note'),resources=state.resources.filter(r=>r.type==='lesson-note');return heading('Good notes. Lasting knowledge.','Keep a daily record of your discoveries. Your teacher will help you stay on track.',staff()?btn('new-resource','Upload lesson notes','primary','data-type="lesson-note"'):btn('submit-note',`${icon('camera')} Submit my notes`,'primary'))+`<div class="grid"><section class="card"><h2>${staff()?'Student notes to review':'Your notebook check-ins'}</h2>${!staff()?`<p class="small muted">The last seven days · submitted dates are highlighted.</p><div class="notes-days">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA',{timeZone:'Africa/Lagos'});return `<span class="day ${ns.some(n=>n.date===key)?'done':''}">${d.toLocaleDateString('en-NG',{weekday:'short'})}<strong>${d.getDate()}</strong></span>`;}).join('')}</div>`:''}${ns.length?ns.map(n=>`<div class="thread"><div class="row between"><strong>${staff()?esc(n.name)+' · ':''}${esc(n.frequency)} notes</strong><span class="badge ${n.status==='Marked'?'':'orange'}">${esc(n.status)}</span></div><p class="small muted">${esc(n.date)} · ${n.week?'Week '+esc(n.week):'Learning week not linked'}</p>${!staff()&&!n.week?btn('note-link-week','Choose learning week','',`data-id="${n.id}"`):''}${staff()?btn('review-submission','Open & mark','','data-id="'+n.id+'"'):submissionFeedback(n)}</div>`).join(''):empty('A fresh page awaits',staff()?'No student notes have been submitted for this term.':'Snap your notes and submit them for a teacher check.','notes')}${staff()?`<h3 class="gap">Still to submit</h3><p class="small muted">${state.students.filter(v=>v.status==='ACTIVE'&&!ns.some(n=>n.student===v.id)).map(v=>esc(v.name)).join(' · ')||'All active students have a note submission.'}</p>`:''}</section><section class="card"><h2>From your teacher’s notebook</h2><p class="small muted">Lesson notes, reading material and class handouts.</p>${resources.length?resources.map(r=>`<div class="thread"><h3>${esc(r.title)}</h3><p class="small muted">${esc(r.teacher)} · ${esc(r.day)}</p><p class="small">${esc(r.text)}</p>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open lesson notes ↗</a>`:''}<div class="row">${(r.files||[]).map(f=>btn('view-file','View notes page','',`data-id="${f}"`)).join('')}</div></div>`).join(''):empty('Your teacher is preparing the notes','Lesson notes for this term will appear here.','notes')}</section></div>`;}
function scores(){const list=tab==='all'?state.scores:state.scores.filter(s=>s.type===tab);return heading('See how far you’ve come.','Your scores are a guide to your next step. Every improvement matters.',staff()?btn('new-score','Enter a score','primary'):'')+`<div class="tabs">${['all','Test','Exam'].map(t=>btn('set-tab',t==='all'?'All scores':t+' scores',tab===t?'active':'',`data-tab="${t}"`)).join('')}</div>${list.length?`<div class="grid three">${list.map(s=>`<section class="card"><span class="badge">${esc(s.type)} · ${esc(s.subject)}</span><p class="score-number">${s.score}<span class="muted" style="font-size:18px"> / ${s.max}</span></p><div class="progress-line"><span style="width:${s.score/s.max*100}%"></span></div><p class="small">${esc(s.remark||'Keep learning. Keep growing.')}</p>${staff()?`<p class="small muted">${esc(state.students.find(v=>v.id===s.student)?.name)}</p>`:''}</section>`).join('')}</div>`:empty('Your next milestone is ahead','Your teacher will enter your test and exam scores here.','scores')}`;}
function progressPage(){const p=progressValues();return heading(staff()?'Every learner, moving forward.':'Small steps add up.','Follow lessons, practice, reflections and submissions throughout the selected term.',staff()?btn('export-report',`${icon('download')} Export report`):'')+`<div class="grid three"><section class="card"><h3>Lesson completion</h3><div class="score-number">${p.percent}%</div><p class="small muted">${p.completed} / ${p.total} lessons${staff()?' · all students':''}</p></section><section class="card"><h3>Practice accuracy</h3><div class="score-number">${p.accuracy}%</div><p class="small muted">Based on the latest answer per practice question.</p></section><section class="card"><h3>Reflection check-ins</h3><div class="score-number">${state.reflections.length}</div><p class="small muted">A pause to turn information into understanding.</p></section></div><div class="grid gap"><section class="card"><h2>Progress by week</h2><div class="chart">${state.weeks.map(w=>{const n=state.progress.filter(p=>p.complete&&String(p.lesson).startsWith(w.id+'-')).length;return `<div class="chart-column"><span>${n}</span><div class="chart-bar" style="height:${Math.min(90,n/3*90)}%"></div><span>W${w.id}</span></div>`;}).join('')}</div><p class="small muted">Completed lessons · Practice ≥ 60% and reflection submitted</p></section><section class="card"><h2>Your habits, at a glance</h2><div class="mini-stat"><span>Assignments submitted</span><strong>${p.submitted}</strong></div><div class="mini-stat"><span>Work reviewed by teacher</span><strong>${state.submissions.filter(s=>s.status==='Marked').length}</strong></div><div class="mini-stat"><span>Class questions</span><strong>${state.questions.length}</strong></div></section></div>${staff()?`<section class="card gap"><h2>A little extra encouragement</h2><p class="small muted">Students with no completed lessons or missing assignments / notes in this term.</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Lessons</th><th>Assignments</th><th>Notes</th></tr></thead><tbody>${state.students.filter(s=>s.status==='ACTIVE').map(s=>`<tr><td>${esc(s.name)}</td><td>${state.progress.filter(p=>p.student===s.id&&p.complete).length}</td><td>${state.submissions.filter(p=>p.student===s.id&&p.kind==='assignment').length}/${state.assignments.length}</td><td>${state.submissions.filter(p=>p.student===s.id&&p.kind==='note').length}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function discussionForm(){return `<form data-form="question">${lesson?'':select('lesson','Choose a lesson',state.weeks.filter(w=>w.unlocked).flatMap(w=>w.lessons).map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join(''))}${area('text','What are you wondering about?','Ask a question, share a discovery, or upload a photo.',false)}<label class="small" for="question-image">Attach a question photo (optional)</label><input id="question-image" type="file" accept="image/*" capture="environment" data-purpose="question"><div id="upload-status" class="small" role="status"></div><div id="upload-preview" class="file-preview"></div><button class="primary gap">Share with my class</button></form>`;}
function threads(qs){return qs.length?qs.map(q=>`<article class="thread"><div class="row"><span class="avatar">${esc(initials(q.name))}</span><div><strong class="small">${esc(q.name)}</strong><div class="small muted">Lesson ${esc(q.lesson)}</div></div></div><p>${esc(q.text)}</p><div class="row">${(q.files||[]).map(f=>btn('view-file','View question photo','',`data-id="${f}"`)).join('')}</div>${q.replies.map(r=>`<div class="reply ${r.role!=='STUDENT'?'teacher':''}"><strong>${esc(r.name)} ${r.role!=='STUDENT'?'<span class="badge">Teacher</span>':''}</strong><br>${esc(r.text)}</div>`).join('')}<form data-form="reply" data-id="${q.id}" class="row"><label class="sr-only" for="reply-${q.id}">Your reply</label><input id="reply-${q.id}" name="text" placeholder="Help a classmate understand…" required style="flex:1"><button type="submit">Reply</button></form></article>`).join(''):empty('Curiosity is welcome here','Be the first to ask a question about this lesson.','question');}
function questions(){const qs=tab==='unanswered'?state.questions.filter(q=>!q.replies.some(r=>r.role!=='STUDENT')):state.questions;return heading('Wonder out loud.','Questions, ideas and “aha!” moments, shared with your class.')+`<div class="grid"><section class="card"><div class="section-head"><h2>The class conversation</h2></div><div class="tabs">${btn('set-tab','All questions',tab==='all'?'active':'','data-tab="all"')}${btn('set-tab','Awaiting a teacher',tab==='unanswered'?'active':'','data-tab="unanswered"')}</div>${threads(qs)}</section><section class="card" style="align-self:start"><h2>Ask your next good question.</h2>${state.weeks.some(w=>w.unlocked)?discussionForm():empty('A lesson comes first','Questions open when your teacher unlocks a lesson.','lock')}</section></div>`;}
function resourceVideos(){const rs=state.resources.filter(r=>r.type==='recording');return rs.length?video(rs.at(-1)):empty('A recording is on its way','Your teacher can add a recording for this topic.','recording');}
function video(r){let embed='';try{const u=new URL(r.url);if(['www.youtube.com','youtube.com','youtu.be'].includes(u.hostname)){const id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v');if(/^[\w-]{11}$/.test(id||''))embed=`https://www.youtube-nocookie.com/embed/${id}`;}if(u.hostname==='vimeo.com'&&/^\/\d+$/.test(u.pathname))embed='https://player.vimeo.com/video'+u.pathname;}catch{}return `<h3>${esc(r.title)}</h3><p class="small muted">${esc(r.day)} · ${esc(r.teacher)}</p>${embed?`<iframe src="${esc(embed)}" title="${esc(r.title)}" allowfullscreen loading="lazy"></iframe>`:r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open class recording ↗</a>`:''}`;}
function recordings(){const rs=state.resources.filter(r=>r.type==='recording');return heading('Rewind. Revisit. Rediscover.','Your classroom, ready whenever you are.',staff()?btn('new-resource','Add a recording','primary','data-type="recording"'):'')+(rs.length?`<div class="grid">${rs.map(r=>`<section class="card">${video(r)}</section>`).join('')}</div>`:empty('Your replay shelf is ready','Your teacher’s recordings for this subject and term will appear here.','recording'));}
function live(){const rs=state.resources.filter(r=>r.type==='live');return heading('Great ideas happen together.','Join your subject’s live class and bring your questions.',staff()?btn('new-resource','Add a live class','primary','data-type="live"'):'')+(rs.length?`<div class="grid">${rs.map(r=>`<section class="card live-card"><span class="eyebrow">${esc(subject)} · ${esc(className)}</span><h3>${esc(r.title)}</h3><p>${esc(r.day)} · ${esc(r.teacher)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Join live class &nbsp; ↗</a></section>`).join('')}</div>`:empty('Your seat is saved','Your teacher will post the link to your next live class here.','live'));}
function teaching(){const subs=state.submissions.filter(v=>['Submitted','Resubmitted','Late','Under review'].includes(v.status));return heading('A space to help minds grow.','Open the next lesson, review a little effort, and guide the next discovery.',btn('course-builder','Design weekly lesson','primary')+` <button data-page="students">${icon('users')} Students</button> <button data-page="progress">${icon('progress')} Class progress</button>`)+`<div class="grid three">${[['studio-open-assignments','assignment','Write an assignment'],['new-resource','notes','Share lesson notes'],['new-score','scores','Enter test / exam scores']].map(([a,i,l])=>btn(a,`${icon(i)} ${l}`,'card',a==='new-resource'?'data-type="lesson-note"':'')).join('')}</div><section class="card gap"><h2>Open a week. Start a discovery.</h2><div class="stack">${state.weeks.map(w=>`<div class="row between"><div><strong class="small">Week ${w.id} · ${esc(w.title)}</strong><p class="small muted" style="margin:4px 0">${(state.allocations||[]).length?'Your assigned subject':'School content'}</p></div>${btn('studio-open-week','Edit in Lesson Studio','',`data-week="${w.id}"`)}</div>`).join('')||empty('No content yet','SS1 Mathematics, first term is the seeded curriculum.')}</div></section><div class="grid gap"><section class="card"><h2>Work awaiting your feedback · ${subs.length}</h2>${subs.length?subs.map(s=>`<div class="assignment-row"><div><h3>${esc(s.name)}</h3><p>${s.kind==='note'?'Notes':'Assignment'} · ${esc(s.date||s.created.slice(0,10))}</p></div>${btn('review-submission','Review →','',`data-id="${s.id}"`)}</div>`).join(''):empty('A clear desk','Student submissions will arrive here.','assignment')}</section><section class="card"><h2>Reflections from your students</h2>${state.reflections.length?state.reflections.map(r=>`<div class="thread"><strong class="small">${esc(r.name)} · ${r.scope==='week'?'Week '+esc(r.week):'Subtopic '+esc(r.lesson)}</strong><p>${esc(r.learnt)}</p><p class="small muted">Still wondering: ${esc(r.question)}</p><p class="small">Confidence: ${r.confidence||'—'}/5 · Difficult part: ${esc(r.difficult||'Not specified')}</p>${r.reply?`<div class="feedback">${esc(r.reply)}</div>`:''}<form data-form="reflection-reply" data-id="${r.id}" class="stack">${area('text','Your response')}<button>Send feedback</button></form></div>`).join(''):empty('Thoughts, soon to be shared','Students’ lesson reflections will appear here.','question')}</section></div>`;}
function admin(){if(user.role!=='ADMIN')return empty('Administrator access required','Use your assigned teaching workspace.','lock');const students=tab==='pending'?state.students.filter(s=>s.status==='PENDING'):state.students;return heading('A school full of possibilities.','Manage access, support your teachers, and keep every learner in the right place.',btn('add-user','Add student / teacher','primary')+' <button data-page="progress">Monitor students</button>')+`<div class="grid three"><section class="card"><span class="muted small">Students awaiting approval</span><p class="score-number">${state.students.filter(s=>s.status==='PENDING').length}</p>${btn('bulk-approve','Approve all pending')}</section><section class="card"><span class="muted small">Active students</span><p class="score-number">${state.students.filter(s=>s.status==='ACTIVE').length}</p><span class="small muted">${state.classes.length} classes · ${state.subjects.length} subjects</span></section><section class="card"><span class="muted small">Teachers</span><p class="score-number">${state.teachers.length}</p>${btn('assign-teacher','Assign a subject')}</section></div>${studentDirectory()}${adminDirectoryPanel()}<div class="grid gap"><section class="card"><h2>Teachers & subjects</h2><p class="small muted">Search and filter the directories above to manage teachers, subjects and teaching assignments.</p><div class="row">${btn('assign-teacher','Assign teacher')}${btn('roster-teacher-privileges','Set teacher privileges')}</div></section><section class="card"><h2>School structure & term access</h2><div class="row">${btn('new-class','Add class')}${btn('new-subject','Add subject')}${btn('toggle-term','Manage selected term','',`data-key="${esc(className+':'+subject+':'+term)}"`)}</div><p class="small muted">${esc(className)} · ${esc(subject)} · ${termNames[term-1]}<br>Term status: ${state.termLocks.includes(`${className}:${subject}:${term}`)?'Locked by administrator':term>(state.currentTerm||1)?'Upcoming (not open to students)':'Open to approved students'}</p><p class="small muted">Previous terms remain readable unless locked. Session: ${esc(sessionLabel())}.</p></section></div><section class="card gap"><h2>Recent administration activity</h2>${state.audit.length?state.audit.slice(0,10).map(a=>`<div class="mini-stat"><span>${esc(a.action)}</span><small>${new Date(a.at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})}</small></div>`).join(''):empty('A clean slate','Approval and access changes will be logged here.','settings')}</section>`;}
function more(){return heading('Your lab, at a glance.','Everything you need, a tap away.')+`<div class="stack">${[...navigation.filter(v=>!['home','learn','assignments','notes'].includes(v[0])),...(staff()?[['students','Students','users'],['teaching','Teaching workspace','settings']]:[]),...(user.role==='ADMIN'?[['admin','School management','users']]:[])].map(([id,label,ic])=>`<button data-page="${id}" class="row between card"><span>${icon(ic)} &nbsp;${id==='progress'&&staff()?'Class progress':label}</span>${icon('chevron')}</button>`).join('')}${btn('theme',`${icon('sun')} Change light / dark mode`)}${btn('logout',`${icon('logout')} Sign out`,'danger')}</div>`;}
function modal(title,html){files=[];const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('close-modal',icon('close'),'subtle','aria-label="Close dialog"')}</div>${html}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();files=[];}
async function openLesson(id){lesson=await api(`lesson/${id}?${query()}`);page='lesson';lessonTab='learn';files=[];render();window.scrollTo(0,0);}
function resourceModal(type){modal(type==='live'?'Let’s bring the class together.':type==='recording'?'Save a lesson for later.':'Share your lesson notes.',`<form data-form="resource" data-type="${type}">${field('title','Title')}${field('day',type==='live'?'Class date and time':'Lesson date','datetime-local','',false)}${field('url',type==='live'?'Live classroom link':'Video / document link (optional)','url','',type==='live')}${type==='recording'?uploadBox('recording'):type==='lesson-note'?area('text','Lesson notes','Write or paste your lesson notes here.',false)+uploadBox('lesson-note'):''}<button type="submit" class="primary gap">Publish to ${esc(className)}</button></form>`);}
function reviewModal(sub){if(!sub)return;modal(`Feedback for ${esc(sub.name)}`,`<p class="small muted">${sub.kind==='note'?'Notebook submission':'Assignment submission'} · ${esc(sub.date||sub.created.slice(0,10))}${sub.week?' · Week '+esc(sub.week):''}</p><div class="row">${sub.files.map(f=>btn('view-file','Open page ↗','',`data-id="${f}"`)).join('')}</div><form data-form="mark" data-id="${sub.id}" class="gap">${field('score','Score out of '+(sub.max||(sub.kind==='note'?state.policy.noteMaximum:100)),'number',sub.score??'')}${select('status','Review result',options(['Marked','Returned for correction'],sub.status))}${area('feedback','Your feedback','Be specific, kind, and helpful.')}<button class="primary">Save score & feedback</button></form>`);}
async function fileUrl(id){return (await api('file/'+id+'?'+query())).url;}
async function loadImages(){}
async function compressImage(file){if(!file.type.startsWith('image/'))throw Error('Please choose an image.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.83,blob;do{blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));quality-=.12;}while(blob.size>400*1024&&quality>.2);if(blob.size>650*1024)throw Error('This image is still too large. Try photographing one page at a time.');return blob;}
function queueDatabase(){return new Promise((resolve,reject)=>{const req=indexedDB.open('olawale-private-upload-queue',1);req.onupgradeneeded=()=>req.result.createObjectStore('queue',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function queueOp(mode,work){const db=await queueDatabase();return new Promise((resolve,reject)=>{const tr=db.transaction('queue',mode),req=work(tr.objectStore('queue'));tr.oncomplete=()=>{db.close();resolve(req?.result);};tr.onerror=()=>{db.close();reject(tr.error);};});}
async function uploadBlob(blob,purpose,savedContext=ctx()){const token=await api('upload-token',{...savedContext,purpose});const r=await fetch(token.url,{method:'PUT',headers:{'X-CSRF-Token':csrf,'Content-Type':blob.type||'application/octet-stream'},body:blob});const v=await r.json();if(!r.ok)throw Error(v.error);return v.id;}
let uploading=0;
async function addUploads(input){const selected=[...input.files];if(selected.length+files.length>10)throw Error('Choose up to 10 pages.');const status=$('#upload-status');uploading++;try{for(let i=0;i<selected.length;i++){if(status)status.textContent=`Preparing page ${i+1} of ${selected.length}…`;const blob=await compressImage(selected[i]),preview=URL.createObjectURL(blob);if($('#upload-preview'))$('#upload-preview').insertAdjacentHTML('beforeend',`<img src="${preview}" alt="Selected page ${i+1}">`);if(!navigator.onLine){await queueOp('readwrite',s=>s.put({id:crypto.randomUUID(),user:user.id,context:ctx(),purpose:input.dataset.purpose,blob}));if(status)status.textContent='Saved on this device. Reconnect to upload, then attach the recovered pages before submitting.';continue;}let id;for(let attempt=0;attempt<3;attempt++){try{id=await uploadBlob(blob,input.dataset.purpose);break;}catch(e){if(attempt===2){await queueOp('readwrite',s=>s.put({id:crypto.randomUUID(),user:user.id,context:ctx(),purpose:input.dataset.purpose,blob}));throw Error('Upload could not finish. Your image is queued on this device; use Recover queued photos after reconnecting.');}}}files.push(id);if(status)status.textContent=`${files.length} page${files.length===1?'':'s'} uploaded and ready.`;}}finally{uploading--;input.value='';}}
async function recoverQueue(){const items=(await queueOp('readonly',s=>s.getAll())).filter(v=>v.user===user.id);if(!items.length){toast('No queued photos for this account.');return;}modal('Recover your queued photos',`<p class="small muted">Queued photos are kept on this device until recovered or cleared. Uploads belong to the original class, subject and term.</p><div class="stack">${items.map(v=>`<div class="card"><span class="small">${esc(v.context.class)} · ${esc(v.context.subject)} · ${termNames[v.context.term-1]} · ${esc(v.purpose)}</span><div class="row gap">${btn('recover-item','Upload & recover','primary',`data-id="${v.id}"`)}${btn('delete-queued','Delete queued photo','danger',`data-id="${v.id}"`)}</div></div>`).join('')}</div>`);}
const recovered=new Map();
function recoveredButton(purpose){const key=JSON.stringify({...ctx(),purpose});const ids=recovered.get(key);return ids?.length?btn('attach-recovered',`Attach ${ids.length} recovered photo${ids.length===1?'':'s'}`,'gap',`type="button" data-purpose="${purpose}"`):'';}
const originalUploadBox=uploadBox;
uploadBox=function(purpose){return originalUploadBox(purpose)+recoveredButton(purpose)+btn('recover-queue','Recover queued photos','subtle','type="button"');};
document.addEventListener('click',async e=>{const target=e.target.closest('button,a[data-action]');if(!target)return;const a=target.dataset.action;if(!a&&!target.dataset.page)return;if(target.type==='submit'&&!a&&target.form)return;if(a)e.preventDefault();try{
 if(target.dataset.page){await navigate(target.dataset.page);return;}
 if(a.startsWith('go-')){await navigate(a.slice(3));return;}
 switch(a){
 case 'auth-toggle':authMode=authMode==='login'?'register':'login';auth();break;
 case 'show-password':{const p=$('#password');p.type=p.type==='password'?'text':'password';target.textContent=p.type==='password'?'Show':'Hide';break;}
 case 'demo':{await enterAccount(await api('demo-login',{role:target.dataset.role}));break;}
 case 'logout':await api('logout',{});user=null;csrf='';state=null;auth();break;
 case 'theme':document.body.classList.toggle('dark');localStorage.setItem('olawale-theme',document.body.classList.contains('dark')?'dark':'light');break;
 case 'close-modal':closeModal();break;
 case 'set-tab':tab=target.dataset.tab;render();break;
 case 'lesson-tab':lessonTab=target.dataset.tab;files=[];render();break;
 case 'open-lesson':await openLesson(target.dataset.id);break;
 case 'show-example':$('#worked-step').textContent=lesson.example.explanation;target.disabled=true;break;
 case 'bit':{const i=Number(target.dataset.i);widgetBits[i]=1-widgetBits[i];target.classList.toggle('on');target.innerHTML=`${widgetBits[i]}<br><small>${2**(5-i)}</small>`;updateWidgets();break;}
 case 'hint':{const q=[...lesson.questions,...lesson.quiz].find(q=>q.id===target.dataset.id);target.closest('.question').querySelector('.answer-feedback').textContent=q.kind==='boolean'?'First solve the calculation, then compare it with the statement.':'Identify the given values. Review the worked example, then apply the same method.';break;}
 case 'assignment-open':{const assignment=state.assignments.find(v=>v.id===target.dataset.id);if(!assignment||!staff()&&assignment.available===false){toast('Your teacher has not released this assignment.');break;}if(staff()){page='assignments';render();break;}const mine=state.submissions.find(v=>v.assignment===assignment.id);
  const body=assignment.document?.blocks?.length?`<div class="lesson-document">${lessonRendering.renderLessonDocument(assignment.document)}</div>`:`<p>${esc(assignment.instructions)}</p>`;
  const finished=mine&&!assignment.resubmission&&!['Returned for correction','Needs redo'].includes(mine.status);
  const form=finished?submissionFeedback(mine):assignment.mode==='ONLINE'?`<form data-form="assignment-online" data-id="${assignment.id}" novalidate>${(assignment.questions||[]).map((q,i)=>`<div class="question"><p>${i+1}. ${promptHTML(q.prompt)}${q.marks>1?` <span class="small muted">(${q.marks} marks)</span>`:''}</p>${answerField(q,q.id,'a-'+q.id,'Answer '+(i+1))}</div>`).join('')}<button class="primary gap">Submit my answers</button><div class="answer-feedback" role="status"></div></form>`:`<form data-form="submission" data-kind="assignment" data-id="${assignment.id}">${uploadBox('assignment')}<button class="primary gap">Submit to my teacher</button></form>`;
  modal(esc(assignment.title),`<p class="small muted">${assignment.due?'Due '+esc(assignmentDeadline(assignment.due))+' · ':''}${esc(subject)} · ${assignment.max} marks</p>${body}${form}`);lessonRendering.hydrateLessonMath($('#modal'));break;}
 case 'assignment-lock':await api('assignment-release',{id:target.dataset.id,status:'LOCKED'});await refresh();render();toast('Locked. Students can no longer open it.');break;
 case 'assignment-release-open':{const a=state.assignments.find(v=>v.id===target.dataset.id);if(!a)break;const tomorrow=new Date(Date.now()+7*864e5).toLocaleDateString('en-CA',{timeZone:'Africa/Lagos'});modal('Release to students',`<form data-form="assignment-release" data-id="${a.id}"><p>${esc(a.title)}</p>${select('status','When should students see it?',`<option value="PUBLISHED">Now, I have taught this in class</option><option value="SCHEDULED">At a date and time I choose</option>`)}${field('releaseAt','Release at (only if scheduled)','datetime-local','',false)}${field('due','Deadline','date',a.due||tomorrow)}<button class="primary gap">Release</button></form>`);break;}
 case 'submit-note':modal('A notebook worth keeping.',`<form data-form="submission" data-kind="note">${field('date','Date of notes','date',new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Lagos'}))}${select('frequency','Submission type',options(['Daily','Weekly']))}${select('week','Learning week',`<option value="" disabled selected>Choose the week these notes belong to</option>`+state.weeks.filter(w=>w.lessons.some(l=>l.available)).map(w=>`<option value="${w.id}">Week ${w.id} · ${esc(w.title)}</option>`).join('')).replace('<select ','<select required ')}<p class="small muted">Daily and weekly notes are recorded against this learning week.</p>${uploadBox('note')}<button class="primary gap">Submit my notes</button></form>`);break;
 case 'view-file':{const src=await fileUrl(target.dataset.id);const w=window.open('','_blank');if(w){w.opener=null;w.location=src;}else toast('Allow a new tab to view the submission photo.');break;}
 case 'edit-course':{const course=await api('course?'+query());modal('Your subject’s weekly lessons',`<p class="small muted">Advanced content editor. Edit the weekly lesson JSON, including objectives, explanation, examples, practice and topic quiz. Keep IDs stable to preserve progress. Review any teacher-authored maths answers before publishing.</p><form data-form="course" data-revision="${esc(course.revision)}"><label for="course-json">Weekly course content (JSON)</label><textarea id="course-json" name="weeks" style="width:100%;min-height:330px;font-family:monospace;font-size:11px" required>${esc(JSON.stringify(course,null,2))}</textarea><button class="primary gap">Validate & publish course</button></form>`);break;}
 case 'new-resource':resourceModal(target.dataset.type||'lesson-note');break;
 case 'new-score':modal('Record a learning milestone.',`<form data-form="score">${select('student','Student',options(state.students.filter(s=>s.status==='ACTIVE')))}${select('type','Assessment',options(['Test','Exam']))}<div class="grid form-grid">${field('title','Assessment title')}${field('date','Assessment date','date',new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Lagos'}))}${field('score','Score','number')}${field('max','Maximum score','number','100')}</div>${area('remark','Remark','A helpful next step for the student.',false)}<label class="row small"><input type="checkbox" name="published"> Publish result to this student now</label><button class="primary">Save result</button></form>`);break;
 case 'review-submission':reviewModal(state.submissions.find(v=>v.id===target.dataset.id));break;
 case 'review-assignment':{const subs=state.submissions.filter(v=>v.assignment===target.dataset.id);modal('Your students’ working.',subs.length?subs.map(s=>`<div class="assignment-row"><div><h3>${esc(s.name)}</h3><p>${esc(s.status)} ${s.score!=null?'· '+s.score+'/100':''}</p></div>${btn('review-submission','Open & mark','',`data-id="${s.id}"`)}</div>`).join(''):empty('No submissions yet','Your students’ work will appear here.','assignment'));break;}
 case 'allow-resubmit':await api('resubmission',{id:target.dataset.id,enabled:target.dataset.enabled==='1'});await refresh();render();toast('Resubmission setting saved.');break;
 case 'student-status':await api('student-status',{id:target.dataset.id,status:target.dataset.status});await refresh();render();toast('Student access updated.');break;
 case 'bulk-approve':for(const s of state.students.filter(v=>v.status==='PENDING'&&(!v.photoRequired||v.photoId)))await api('student-status',{id:s.id,status:'ACTIVE'});await refresh();render();toast('Eligible students approved. Add initial photos for any students still pending.');break;
 case 'reject-student':modal('Registration decision',`<form data-form="reject" data-id="${target.dataset.id}">${area('reason','Reason for rejecting this registration')}<button class="danger">Reject registration</button></form>`);break;
 case 'move-student':modal('Move student to another class',`<form data-form="move" data-id="${target.dataset.id}">${select('newClass','New class',options(state.classes))}<button class="primary">Save class</button></form>`);break;
 case 'add-user':modal(user.role==='ADMIN'?'Welcome a new learner or teacher.':'Register a student',`<form data-form="add-user">${select('role','Account type',options(user.role==='ADMIN'?['STUDENT','TEACHER']:['STUDENT'],target.dataset.role||'STUDENT'))}${select('class','Student class',options(rosterClasses(),className))}${field('name','Full name')}${field('email','Email','email')}${field('password','Temporary password (10+ characters)','password')}${field('admission','Admission number (students)','text','',false)}${registrationPhotoFields(target.dataset.role!=='TEACHER')}<p class="small muted">Choose the class above. Student accounts remain pending until an authorised administrator or teacher approves them.${user.role==='ADMIN'?' Staff accounts can sign in immediately.':''}</p><button class="primary">Create account</button></form>`);break;
 case 'assign-teacher':modal('The right teacher. The right subject.',`<form data-form="allocation">${select('teacher','Teacher',options(state.teachers,target.dataset.teacher))}${select('class','Class',options(state.classes,className))}${select('subject','Subject',options(state.subjects,target.dataset.subject||subject))}<button class="primary">Assign teacher</button></form>`);break;
 case 'remove-allocation':await api('allocation',{teacher:target.dataset.teacher,class:target.dataset.class,subject:target.dataset.subject,remove:true});await refresh();render();break;
 case 'new-class':case 'new-subject':modal(a==='new-class'?'Add a class':'Add a subject',`<form data-form="catalog" data-kind="${a==='new-class'?'class':'subject'}">${field('name','Name')}<button class="primary">Add to school</button></form>`);break;
 case 'toggle-term':modal('Term access',`<p>${esc(className)} · ${esc(subject)} · ${termNames[term-1]}</p><div class="row">${btn('save-term','Open term','primary','data-locked="0"')}${btn('save-term','Lock term','','data-locked="1"')}</div><p class="small muted">Upcoming terms remain closed until selected as the current term.</p>${btn('activate-term','Set this as the current term','gap')}`);break;
 case 'save-term':await api('term-lock',{locked:target.dataset.locked==='1'});closeModal();await refresh();render();toast('Term access saved.');break;
 case 'activate-term':await api('current-term',{currentTerm:term});closeModal();await refresh();render();toast('Current academic term updated.');break;
 case 'export-report':downloadCSV('learning-progress.csv',['Student','Class','Completed lessons','Assignments'],state.students.filter(v=>v.status==='ACTIVE').map(s=>[s.name,s.class,state.progress.filter(p=>p.student===s.id&&p.complete).length,state.submissions.filter(v=>v.student===s.id&&v.kind==='assignment').length]));break;
 case 'export-students':downloadCSV('school-students.csv',['Name','Email','Class','Admission','Status'],state.students.map(s=>[s.name,s.email,s.class,s.admission,s.status]));break;
 case 'import-students':modal('Import students from CSV',`<p class="small muted">Header: name,email,password,class,admission. Imported accounts remain pending. Add each student’s initial photo from their profile before approval. Passwords must have at least 10 characters. Review your CSV before import.</p><form data-form="import"><label for="csv">Choose CSV</label><input id="csv" name="csv" type="file" accept=".csv" required><button class="primary gap">Import student accounts</button><p class="small" id="import-status"></p></form>`);break;
 case 'recover-queue':await recoverQueue();break;
 case 'delete-queued':await queueOp('readwrite',s=>s.delete(target.dataset.id));await recoverQueue();break;
 case 'recover-item':{const item=await queueOp('readonly',s=>s.get(target.dataset.id));if(item.user!==user.id)throw Error('This photo belongs to another account.');const id=await uploadBlob(item.blob,item.purpose,item.context),key=JSON.stringify({...item.context,purpose:item.purpose});recovered.set(key,[...(recovered.get(key)||[]),id]);await queueOp('readwrite',s=>s.delete(item.id));toast('Photo recovered. Open the matching submission form and tap Attach recovered photo.');target.textContent='Recovered';target.disabled=true;break;}
 case 'attach-recovered':{const key=JSON.stringify({...ctx(),purpose:target.dataset.purpose}),ids=recovered.get(key)||[];files.push(...ids);recovered.delete(key);target.disabled=true;$('#upload-status').textContent=`${files.length} pages attached.`;break;}
 }
}catch(error){toast(error.message);}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='term-switch'){term=Number(el.value);await navigate(page==='lesson'?'learn':page);}if(el.id==='class-switch'){className=el.value;if(user.role==='TEACHER')subject=state.allocations.find(a=>a.class===className)?.subject||subject;await navigate(page==='lesson'?'learn':page);}if(el.id==='subject-switch'){subject=el.value;await navigate(page==='lesson'?'learn':page);}if(el.type==='file'&&el.dataset.purpose)await addUploads(el);if(el.id==='base-target')updateWidgets();}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.closest('.widget'))updateWidgets();});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(f));const type=f.dataset.form;busy=true;const button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{
 if(type==='auth'){if(authMode==='register'){const r=await api('register',data);$('#auth-message').innerHTML=`<p class="success">${esc(r.message)}</p>`;return;}const result=await api('login',data);user=result.user;csrf=result.csrf;if(user.mustChangePassword){passwordScreen();return;}await enterApp();return;}
 if(type==='change-password'){if(data.newPassword!==data.confirmPassword){$('#auth-message').innerHTML='<p class="error">The two new passwords do not match.</p>';return;}try{const r=await api('change-password',{currentPassword:data.currentPassword,newPassword:data.newPassword});user=r.user;csrf=r.csrf;toast('Password changed. Welcome.');await enterApp();}catch(err){$('#auth-message').innerHTML=`<p class="error">${esc(err.message)}</p>`;}return;}
 if(type==='answer'){const r=await api('practice',{lesson:lesson.id,question:f.dataset.question,answer:formAnswers(f).answer,activeSeconds:Math.max(0,Math.min(300,activitySeconds-lastPracticeActivity))});f.querySelector('.answer-feedback').innerHTML=`<strong class="${r.correct?'correct':'wrong'}">${r.correct?'✓ You’ve got it!':'Keep going. Here’s a little help.'}</strong><br>${esc(r.explanation)}${r.correct?'':`<br>Answer: ${esc(r.answer)}`}`;lastPracticeActivity=activitySeconds;await refresh();const journey=document.querySelector('.lesson-layout aside');if(journey){const progress=state.progress.find(p=>p.lesson===lesson.id);journey.querySelector('.checklist').innerHTML=`<li>Read and explore</li><li>${progress?.accuracy||0}% practice accuracy</li><li>${progress?.reflectionDone?'Reflection submitted':'Reflection still to write'}</li>`;}return;}
 if(type==='reflection'){await api('reflection',{lesson:lesson.id,...data,draft:e.submitter?.name==='saveDraft'});await refresh();render();toast('Reflection saved. One more step in your learning journey.');return;}
 if(type==='question'){if(uploading)throw Error('Wait for your photo upload to finish.');await api('question',{lesson:lesson?.id||data.lesson,text:data.text,files});files=[];await refresh();render();toast('Your question is with the class.');return;}
 if(type==='reply'){await api('reply',{id:f.dataset.id,text:data.text});await refresh();render();toast('Reply shared.');return;}
 if(type==='assignment-online'){const r=await api('assignment-submit',{assignment:f.dataset.id,answers:formAnswers(f)});await refresh();render();f.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);f.querySelector('.answer-feedback').innerHTML=r.graded?`<div class="feedback"><strong>You scored ${r.score} out of ${r.max} (${r.percentage}%)</strong>${r.late?'<p class="small">Submitted after the deadline.</p>':''}${r.results.map((x,i)=>`<details><summary>${i+1}. ${x.correct?'✓ Correct':'Revise this'}</summary>${x.explanation?`<p>${promptHTML(x.explanation)}</p>`:''}${x.answer?`<p><strong>Answer: ${promptHTML(String(x.answer).split('|').join(', '))}</strong></p>`:''}</details>`).join('')}</div>`:'<div class="feedback"><strong>Submitted.</strong> Your teacher will mark it and your score will appear here.</div>';lessonRendering.hydrateLessonMath(f);return;}
 if(type==='assignment-release'){await api('assignment-release',{id:f.dataset.id,status:data.status,releaseAt:data.status==='SCHEDULED'&&data.releaseAt?new Date(data.releaseAt).toISOString():null,due:data.due});closeModal();await refresh();render();toast(data.status==='SCHEDULED'?'Scheduled.':'Released. Students can open it now.');return;}
 if(type==='submission'){if(uploading)throw Error('Wait for your photo upload to finish.');await api('submit',{...data,kind:f.dataset.kind,assignment:f.dataset.id,files});closeModal();await refresh();render();toast('Safely submitted to your teacher.');return;}
 if(type==='course'){let weeks;try{weeks=JSON.parse(data.weeks);}catch{throw Error('The course JSON is not valid. Check commas and brackets.');}await api('course',{weeks,revision:f.dataset.revision});}
 if(type==='resource'){if(uploading)throw Error('Wait for the photo upload.');await api('resource',{...data,type:f.dataset.type,files});}
 if(type==='score')await api('score',{...data,published:new FormData(f).has('published')});
 if(type==='mark')await api('mark',{id:f.dataset.id,...data,rubric:subRubric(data)});
 if(type==='reflection-reply'){await api('reflection-reply',{id:f.dataset.id,text:data.text});await refresh();render();toast('Feedback saved.');return;}
 if(type==='reject')await api('student-status',{id:f.dataset.id,status:'REJECTED',reason:data.reason});
 if(type==='move'){const s=state.students.find(s=>s.id===f.dataset.id);await api('student-status',{id:s.id,status:s.status,newClass:data.newClass});}
 if(type==='add-user'){const photo=new FormData(f).get('profilePhoto');if(photo?.size)data.photoId=(await uploadProfilePhoto(photo,{newStudent:true})).id;delete data.profilePhoto;await api('add-user',data);}
 if(type==='allocation')await api('allocation',data);
 if(type==='catalog')await api('catalog',{kind:f.dataset.kind,...data});
 if(type==='import'){const file=new FormData(f).get('csv'),rows=parseCSV(await file.text()),headers=rows.shift().map(s=>s.toLowerCase().trim());if(!['name','email','password','class','admission'].every(v=>headers.includes(v)))throw Error('CSV needs name,email,password,class,admission headers.');const errors=[];let success=0;for(let i=0;i<rows.length;i++){if(!rows[i].some(Boolean))continue;const row=Object.fromEntries(headers.map((h,j)=>[h,rows[i][j]||'']));try{await api('add-user',{...row,role:'STUDENT',import:true});success++;}catch(e){errors.push(`Row ${i+2}: ${e.message}`);}if($('#import-status'))$('#import-status').textContent=`Imported ${success} accounts…`;}if(errors.length){$('#import-status').textContent=`Imported ${success}. ${errors.join(' ')}`;await refresh();return;}toast(`${success} student accounts imported.`);}
 closeModal();await refresh();render();toast('Saved to your school workspace.');
 }catch(error){if(type==='auth')$('#auth-message').innerHTML=`<p class="error">${esc(error.message)}</p>`;else toast(error.message);}finally{busy=false;if(button)button.disabled=false;}});
function downloadCSV(filename,headers,rows){const value=[headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([value],{type:'text/csv'}));link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function parseCSV(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if(c==='\n'&&!quoted){row.push(value.replace(/\r$/,''));rows.push(row);row=[];value='';}else value+=c;}if(value||row.length){row.push(value.replace(/\r$/,''));rows.push(row);}return rows;}
window.addEventListener('online',()=>{if(user)toast('You’re back online. Use Recover queued photos in a submission form to finish queued uploads.');});
async function boot(){publicConfig=await api('config').catch(()=>({demo:false,selfRegistration:false}));if(localStorage.getItem('olawale-theme')==='dark')document.body.classList.add('dark');try{const r=await api('me');user=r.user;csrf=r.csrf;if(user.mustChangePassword){passwordScreen();return;}academicId=r.currentSessionId;className=user.class||'SS1';page=user.role==='ADMIN'?'admin':user.role==='TEACHER'?'teaching':'home';term=r.currentTerm||1;if(user.role==='TEACHER'&&r.allocations.length){className=r.allocations[0].class;subject=r.allocations[0].subject;}await refresh();render();}catch{auth();}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
